use hec_native_ic::{counted,fp::Fp,poly::Poly,instance::pick_instance};
#[derive(Clone,Debug,PartialEq,Eq)]struct P(Vec<u64>);
impl P{fn new(mut v:Vec<u64>)->Self{while v.last()==Some(&0){v.pop();}Self(v)}fn one()->Self{Self(vec![1])}fn deg(&self)->usize{self.0.len()-1}fn add(&self,b:&Self,f:&Fp)->Self{Self::new((0..self.0.len().max(b.0.len())).map(|i|f.add(*self.0.get(i).unwrap_or(&0),*b.0.get(i).unwrap_or(&0))).collect())}fn scale(&self,k:u64,f:&Fp)->Self{Self::new(self.0.iter().map(|&x|f.mul(x,k)).collect())}fn mul(&self,b:&Self,f:&Fp)->Self{if self.0.is_empty()||b.0.is_empty(){return Self(vec![]);}let mut v=vec![0;self.0.len()+b.0.len()-1];for(i,&x)in self.0.iter().enumerate(){for(j,&y)in b.0.iter().enumerate(){v[i+j]=f.add(v[i+j],f.mul(x,y));}}Self::new(v)}fn pow(&self,n:usize,f:&Fp)->Self{(0..n).fold(Self::one(),|a,_|a.mul(self,f))}fn div(&self,b:&Self,f:&Fp)->(Self,Self){assert!(!b.0.is_empty());let mut r=self.clone();let mut q=vec![0;self.0.len().saturating_sub(b.0.len())+1];let il=f.inv(*b.0.last().unwrap());while !r.0.is_empty()&&r.deg()>=b.deg(){let n=r.deg()-b.deg();let k=f.mul(*r.0.last().unwrap(),il);q[n]=k;for i in 0..b.0.len(){r.0[n+i]=f.sub(r.0[n+i],f.mul(k,b.0[i]));}r=Self::new(r.0);} (Self::new(q),r)}fn exact(&self,b:&Self,f:&Fp)->Self{let(q,r)=self.div(b,f);assert!(r.0.is_empty());q}fn deriv(&self,f:&Fp)->Self{Self::new((1..self.0.len()).map(|i|f.mul(i as u64,self.0[i])).collect())}fn monic(&self,f:&Fp)->Self{self.scale(f.inv(*self.0.last().unwrap()),f)}fn gcd(&self,b:&Self,f:&Fp)->Self{let(mut a,mut b)=(self.clone(),b.clone());while !b.0.is_empty(){let r=a.div(&b,f).1;a=b;b=r;}a.monic(f)}fn eval(&self,t:u64,f:&Fp)->u64{self.0.iter().rev().fold(0,|a,&x|f.add(f.mul(a,t),x))}}
fn arr(l:&str,k:&str)->P{P::new(l.split(&format!("{k}=[")).nth(1).unwrap().split(']').next().unwrap().split(',').map(|x|x.trim().parse().unwrap()).collect())}
fn native(p:&P)->Poly{Poly::from_coeffs(&p.0)}
fn sqrt(p:&P,f:&Fp)->P{assert_eq!(p.deg()%2,0);let n=p.deg()/2;let lead=f.sqrt(*p.0.last().unwrap()).expect("nonsquare quotient scalar");let mut v=vec![0;n+1];v[n]=lead;let den=f.inv(f.mul(2,lead));for i in(0..n).rev(){let sq=P(v.clone()).pow(2,f);let known=*sq.0.get(n+i).unwrap_or(&0);v[i]=f.mul(f.sub(p.0[n+i],known),den);}let out=P::new(v);assert_eq!(out.pow(2,f),*p);out}
fn disc(a:&P,c:&P,d2:&P,e:&P,f:&Fp)->P{let terms=[(256,a.pow(3,f).mul(&e.pow(3,f),f)),(-128,a.pow(2,f).mul(&c.pow(2,f),f).mul(&e.pow(2,f),f)),(144,a.pow(2,f).mul(c,f).mul(d2,f).mul(e,f)),(-27,a.pow(2,f).mul(&d2.pow(2,f),f)),(16,a.mul(&c.pow(4,f),f).mul(e,f)),(-4,a.mul(&c.pow(3,f),f).mul(d2,f))];terms.iter().fold(P(vec![]),|s,(k,p)|s.add(&p.scale(f.from_i64(*k),f),f))}
fn main(){counted::disable();let raw=include_str!("../native-smith-affine/CONTROL.txt");let mut maps=0;let mut comparisons=0;let mut connected=0;for(idx,l)in raw.lines().enumerate().filter(|(_,l)|l.starts_with("MAP ")){let p:u64=l.split_whitespace().find_map(|w|w.strip_prefix("p=")).unwrap().parse().unwrap();let f=Fp::new(p);let inst=pick_instance(p,3).unwrap();let n=arr(l,"normalized_n");let d=arr(l,"normalized_d");let r=arr(l,"monic_square_root");let sl=raw.lines().nth(idx+1).unwrap();let a=arr(sl,"delta4");let c=arr(sl,"delta2");let d2=arr(sl,"delta1_squared");let e=arr(sl,"delta0");assert_eq!(a.deg(),4);assert_eq!(a.gcd(&a.deriv(&f),&f).deg(),0);assert_eq!(r.deg(),3);assert_eq!(r.gcd(&r.deriv(&f),&f).deg(),0);assert_eq!(a.gcd(&r,&f).deg(),0);assert_eq!(d.gcd(&d.deriv(&f),&f).deg(),0);assert_eq!(native(&d).deg(),2);assert_eq!(Poly::gcd(&inst.curve.f,&native(&d),&f).deg(),1);assert_eq!(n.gcd(&d,&f).deg(),0);
let discriminant=disc(&a,&c,&d2,&e,&f);let index=sqrt(&discriminant.exact(&a,&f),&f);assert_eq!(a.mul(&index.pow(2,&f),&f),discriminant);let radical=index.exact(&index.gcd(&index.deriv(&f),&f),&f);let mut residual=index.clone();let mut r_power=0;while residual.div(&r,&f).1.0.is_empty(){residual=residual.exact(&r,&f);r_power+=1;}let mut witness=None;let mut cmp=0;if p==61{let norm=arr(l,"norm_s");let rr=r.scale(f.sqrt(*norm.0.last().unwrap()).unwrap(),&f);for t in 0..p{let av=a.eval(t,&f);if av==0{continue;}let dv=f.neg(f.mul(8,rr.eval(t,&f)));let q=Poly::from_coeffs(&[e.eval(t,&f),dv,c.eval(t,&f),0,av]).monic(&f);assert_eq!(discriminant.eval(t,&f),f.mul(q.disc_monic(&f),f.pow(av,6)));cmp+=1;if witness.is_none()&&Poly::gcd(&q,&q.deriv(&f),&f).deg()==0{let x=Poly::from_coeffs(&[0,1]);let x2=x.powmod(p*p,&q,&f);let x4=x2.powmod(p*p,&q,&f);if Poly::gcd(&q,&x2.sub(&x,&f),&f).deg()==0&&x4==x{witness=Some(t);}}}assert!(witness.is_some(),"no irreducible specialization retained");connected+=1;}
println!("MAP map={maps} p={p} discriminant_degree={} discriminant={:?} square_index_degree={} square_index={:?} index_radical_degree={} norm_root_power={r_power} residual_index={:?} critical_squarefree=true critical_pair_disjoint=true pole_branch_gcd_degree=1 irreducible_quartic_specialization={witness:?} native_discriminant_comparisons={cmp}",discriminant.deg(),discriminant.0,index.deg(),index.0,radical.deg(),residual.0);comparisons+=cmp;maps+=1;}assert_eq!(maps,6);assert_eq!(connected,2);eprintln!("PASS maps=6 exact_polynomial_discriminant_identities=6 connected_F61_specializations=2 native_discriminant_comparisons={comparisons} no_canonical_model_or_speed_claim=true");}
